import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> order = List.of("unit", "component", "integration", "e2e");
        Map<String, int[]> totals = new LinkedHashMap<>();
        for (String kind : order) totals.put(kind, new int[2]);

        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            int tests = numberAfter(line, "Tests run: ");
            int millis = numberAfter(line, "Time elapsed: ");
            String className = line.substring(line.indexOf("-- in ") + "-- in ".length()).trim();
            int[] slot = totals.get(kindOf(className));
            slot[0] += tests;
            slot[1] += millis;
        }
        for (String kind : order) {
            int[] slot = totals.get(kind);
            System.out.println(kind + " " + slot[0] + " " + slot[1]);
        }
        System.out.println(totals.get("e2e")[0] > totals.get("unit")[0] ? "INVERTED" : "OK");
    }

    /** 末尾で種類を決める。ComponentTest は Test より先に当てる。 */
    static String kindOf(String className) {
        if (className.endsWith("E2ETest")) return "e2e";
        if (className.endsWith("ComponentTest")) return "component";
        if (className.endsWith("IT")) return "integration";
        return "unit";
    }

    static int numberAfter(String line, String key) {
        int from = line.indexOf(key) + key.length();
        int to = from;
        while (to < line.length() && Character.isDigit(line.charAt(to))) to++;
        return Integer.parseInt(line.substring(from, to));
    }
}

