import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<String, Integer> counts = new LinkedHashMap<>();
        counts.put("unit", 0);
        counts.put("component", 0);
        counts.put("e2e", 0);
        for (int i = 0; i < n; i++) {
            String type = sc.next();
            counts.merge(type, 1, Integer::sum);
        }
        int wide = counts.get("component") + counts.get("e2e");
        System.out.println("unit=" + counts.get("unit")
                + " component=" + counts.get("component")
                + " e2e=" + counts.get("e2e"));
        System.out.println(wide * 10 > n * 3 ? "top-heavy" : "balanced");
    }
}

