public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int budget = sc.nextInt();
        int n = sc.nextInt();
        int total = 0;
        for (int i = 0; i < n; i++) {
            sc.next();
            total += sc.nextInt();
        }
        String[] stages = {"compile", "test", "scan", "package"};
        String blocked = null;
        for (String stage : stages) {
            if (sc.nextInt() == 0 && blocked == null) {
                blocked = stage;
            }
        }
        System.out.println("total=" + total);
        if (blocked != null) {
            System.out.println("BLOCKED " + blocked);
        } else if (total > budget) {
            System.out.println("TOO_SLOW");
        } else {
            System.out.println("RELEASE");
        }
    }
}
